tone',7:'Perfect 5th',8:'Minor 6th',9:'Major 6th',10:'Minor 7th',11:'Major 7th'};const clock=document.getElementById('clock');const result=document.getElementById('result');const mapping=document.getElementById('mapping');const cx=200,cy=200,R=160;let selectedNote=null;for(let i=0;i<12;i++){const a=-Math.PI/2+2*Math.PI*i/12;const x=cx+R*Math.cos(a)-22;const y=cy+R*Math.sin(a)-22;const div=document.createElement('div');div.className='note '+(perfect.has(i)?'perfect-con':consonant.has(i)?'consonant':'dissonant');div.style.left=x+'px';div.style.top=y+'px';div.textContent=names[i];div.dataset.interval=i;div.addEventListener('click',()=>selectNote(i));clock.appendChild(div);}function selectNote(i){document.querySelectorAll('.note').forEach(n=>{n.classList.remove('highlight');});const neg=(12-i)%12;const noteI=document.querySelector(`[data-interval='${i}']`);const noteNeg=document.querySelector(`[data-interval='${neg}']`);noteI.classList.add('highlight');noteNeg.classList.add('highlight');const iCons=consonant.has(i);const negCons=consonant.has(neg);const preserved=iCons===negCons&&iCons;let html=`<b>${fullNames[i]}</b> (${i}) → <b>−${i} ≡ ${neg}</b> (mod 12) → <b>${fullNames[neg]}</b><br>`;if(i===neg){html+=`<span style='color:#4ecdc4'>Fixed point: maps to itself</span>`;}else if(iCons&&!negCons){html+=`<span style='color:#ff6b6b'>⚠ CONSONANCE BROKEN: ${names[i]} is consonant but ${names[neg]} is dissonant!</span>`;}else if(iCons&&negCons){html+=`<span style='color:#4ecdc4'>✓ Both consonant: ${names[i]} ↔ ${names[neg]}</span>`;}else{html+=`<span style='color:#777'>Both dissonant</span>`;}result.innerHTML=html;}const mapHTML=[];for(const i of[0,3,4,7,8,9]){const neg=(12-i)%12;const ok=consonant.has(neg);mapHTML.push(`<div class='map-item'>${names[i]} (${i})<br><span class='arrow-sym'>↓</span><br>${names[neg]} (${neg})<br><span style='color:${ok?'#4ecdc4':'#ff6b6b'}'>${ok?'✓ consonant':'✗ DISSONANT'}</span></div>`);}mapping.innerHTML=mapHTML.join('');selectNote(7);</script></body></html>"
