div class=\"formula\" id=\"formulaBox\">|C| ≤ 4^(16 − d + 1)</div></div><div class=\"card\"><canvas id=\"chart\" height=\"350\"></canvas></div><div class=\"card\"><h3 style=\"color:#7eb8ff;margin-bottom:10px\">Bound vs. Distance</h3><div id=\"barChart\"></div></div><div class=\"card result\" id=\"resultBox\"></div></div><script>const aS=document.getElementById('aSlider'),lS=document.getElementById('lSlider'),aV=document.getElementById('aVal'),lV=document.getElementById('lVal'),formula=document.getElementById('formulaBox'),chart=document.getElementById('chart'),barDiv=document.getElementById('barChart'),resBox=document.getElementById('resultBox'),ctx=chart.getContext('2d');function update(){const A=+aS.value,L=+lS.value;aV.textContent=A;lV.textContent=L;formula.innerHTML=`|C| ≤ ${A}<sup>(${L} − d + 1)</sup>`;const total=Math.pow(A,L);const data=[];for(let d=1;d<=L;d++){const bound=Math.pow(A,L-d+1);data.push({d,bound,logBound:Math.log10(Math.max(bound,1)),frac:bound/total})}const W=chart.width=chart.offsetWidth*2,H=chart.height=700;ctx.clearRect(0,0,W,H);const pad={l:70,r:30,t:30,b:50};const pw=W-pad.l-pad.r,ph=H-pad.t-pad.b;const maxLog=data[0].logBound;ctx.fillStyle='#1a1a3a';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#2a2a4a';ctx.lineWidth=1;for(let i=0;i<=5;i++){const y=pad.t+ph*(1-i/5);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(W-pad.r,y);ctx.stroke();ctx.fillStyle='#888';ctx.font='20px sans-serif';ctx.textAlign='right';ctx.fillText((maxLog*i/5).toFixed(1),pad.l-8,y+6)}ctx.fillStyle='#888';ctx.font='20px sans-serif';ctx.textAlign='center';ctx.save();ctx.translate(16,H/2);ctx.rotate(-Math.PI/2);ctx.fillText('log₁₀(bound)',0,0);ctx.restore();ctx.fillText('Minimum distance d',W/2,H-8);ctx.beginPath();ctx.strokeStyle='#7eb8ff';ctx.lineWidth=3;data.forEach((p,i)=>{const x=pad.l+pw*(i/(data.length-1||1));const y=pad.t+ph*(1-p.logBound/maxLog);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke();data.forEach((p,i)=>{if(i%(Math.ceil(data.length/12))!==0&&i!==data.length-1)return;const x=pad.l+pw*(i/(data.length-1||1));const y=pad.t+ph*(1-p.logBound/maxLog);ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fillStyle='#ffcc00';ctx.fill();ctx.fillStyle='#aaa';ctx.font='18px sans-serif';ctx.textAlign='center';ctx.fillText(p.d,x,H-pad.b+25)});let html='';const maxBarLog=data[0].logBound;const step=Math.max(1,Math.floor(L/10));for(let i=0;i<data.length;i+=step){const p=data[i];const pct=Math.max(1,p.logBound/maxBarLog*100);html+=`<div class=\"bar-container\"><div class=\"bar-label\">d=${p.d}</div><div class=\"bar\" style=\"width:${pct}%;background:linear-gradient(90deg,#7eb8ff,#3a5a8a)\"></div><div class=\"bar-label\">${p.bound>1e12?'10^'+p.logBound.toFixed(1):p.bound.toLocaleString()}</div></div>`}barDiv.innerHTML=html;const degreeN=L*(A-1);resBox.innerHTML=`<b>Total Library size:</b> ${A}<sup>${L}</sup>${total<1e15?' = '+total.toLocaleString():' ≈ 10<sup>'+Math.log10(total).toFixed(1)+'</sup>'}<br><b>Degree (neighbors per volume):</b> ${degreeN.toLocaleString()}<br><b>Diameter:</b> ${L}<br><b>At d=${Math.min(Math.ceil(L/2),L)}:</b> bound = ${A}<sup>${L-Math.min(Math.ceil(L/2),L)+1}</sup>${Math.pow(A,L-Math.min(Math.ceil(L/2),L)+1)<1e15?' = '+Math.pow(A,L-Math.min(Math.ceil(L/2),L)+1).toLocaleString():''}<br><b>Interpretation:</b> As minimum distance increases, the maximum number of \"meaningful\" volumes drops exponentially — meaning is rare in the Library.`}aS.oninput=update;lS.oninput=update;update()</script></body></html>"
