,[7,7,1],[7,8,12],[7,9,12],[8,0,12],[8,3,12],[8,4,12],[8,7,12],[8,8,12],[8,9,12],[9,0,12],[9,3,12],[9,4,12],[9,7,12],[9,8,12],[9,9,12]];const N=intervals.length;let nodes=intervals.map((iv,i)=>{const a=i*Math.PI*2/N-Math.PI/2;return{...iv,x:W/2+160*Math.cos(a),y:H/2+160*Math.sin(a),vx:0,vy:0,r:iv.type==='perfect'?28:24}});let dragging=null,hover=null,mx=0,my=0;function idxOf(id){return nodes.findIndex(n=>n.id===id)}function draw(){ctx.clearRect(0,0,W,H);edges.forEach(([s,t,w])=>{if(s===t)return;const si=idxOf(s),ti=idxOf(t),n1=nodes[si],n2=nodes[ti];const dx=n2.x-n1.x,dy=n2.y-n1.y,d=Math.sqrt(dx*dx+dy*dy);if(d<1)return;const nx=dx/d,ny=dy/d;const ox=-ny*8,oy=nx*8;const alpha=w===12?0.15:0.06;ctx.beginPath();ctx.moveTo(n1.x+ox,n1.y+oy);ctx.lineTo(n2.x+ox,n2.y+oy);ctx.strokeStyle=`rgba(100,180,255,${alpha})`;ctx.lineWidth=w===12?2:1;ctx.stroke();const ax=n2.x+ox-nx*35,ay=n2.y+oy-ny*35;ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(ax-nx*8+ny*4,ay-ny*8-nx*4);ctx.lineTo(ax-nx*8-ny*4,ay-ny*8+nx*4);ctx.closePath();ctx.fillStyle=`rgba(100,180,255,${alpha*2})`;ctx.fill()});nodes.forEach((n,i)=>{const isHover=hover===i;const glow=isHover?20:0;if(glow){ctx.beginPath();ctx.arc(n.x,n.y,n.r+glow,0,Math.PI*2);ctx.fillStyle=n.type==='perfect'?'rgba(240,192,64,0.15)':'rgba(64,144,240,0.15)';ctx.fill()}ctx.beginPath();ctx.arc(n.x,n.y,n.r,0,Math.PI*2);const col=n.type==='perfect'?'#f0c040':'#4090f0';ctx.fillStyle=isHover?col:col+'cc';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=isHover?2.5:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font=isHover?'bold 13px sans-serif':'12px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(n.id.toString(),n.x,n.y-6);ctx.font='9px sans-serif';ctx.fillStyle='#ccc';ctx.fillText(n.name.split(' ')[0],n.x,n.y+8);if(n.selfLoops>1||n.type==='perfect'){ctx.beginPath();ctx.arc(n.x,n.y-n.r-10,8,0,Math.PI*2);ctx.fillStyle=n.type==='perfect'?'#a06020':'#2060a0';ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 9px sans-serif';ctx.fillText(n.selfLoops.toString(),n.x,n.y-n.r-10)}});requestAnimationFrame(draw)}canvas.addEventListener('mousemove',e=>{const r=canvas.getBoundingClientRect();mx=e.clientX-r.left;my=e.clientY-r.top;if(dragging!==null){nodes[dragging].x=mx;nodes[dragging].y=my;return}hover=null;nodes.forEach((n,i)=>{const dx=mx-n.x,dy=my-n.y;if(dx*dx+dy*dy<n.r*n.r)hover=i});if(hover!==null){const n=nodes[hover];const totalIn=edges.filter(([s,t])=>t===n.id).reduce((a,e)=>a+e[2],0);const totalOut=edges.filter(([s,t])=>s===n.id).reduce((a,e)=>a+e[2],0);infoEl.innerHTML=`<b>${n.name}</b> — interval class ${n.id} semitones<br>Type: <b>${n.type}</b> consonance<br>Self-loops: <b>${n.selfLoops}</b> | Incoming: <b>${totalIn}</b> | Outgoing: <b>${totalOut}</b>`}else{infoEl.innerHTML='Hover over a node to see details. Drag nodes to rearrange.'}});canvas.addEventListener('mousedown',e=>{const r=canvas.getBoundingClientRect();mx=e.clientX-r.left;my=e.clientY-r.top;nodes.forEach((n,i)=>{const dx=mx-n.x,dy=my-n.y;if(dx*dx+dy*dy<n.r*n.r)dragging=i})});canvas.addEventListener('mouseup',()=>{dragging=null});draw()</script></body></html>"
