      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Self-Loop Bottleneck</title><style>*{margin:0;padding:0;box-sizing:border-box}body{background:#0a0a1a;color:#e0e0e0;font-family:'Segoe UI',system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;padding:30px}h1{font-size:1.4em;color:#f0c040;margin-bottom:5px}p.sub{color:#888;font-size:.85em;margin-bottom:25px}.chart{display:flex;align-items:flex-end;gap:18px;height:320px;padding:0 30px}.bar-group{display:flex;flex-direction:column;align-items:center;gap:5px}.bar{width:60px;border-radius:6px 6px 0 0;transition:height 1.5s cubic-bezier(.4,0,.2,1);position:relative;display:flex;align-items:flex-start;justify-content:center;padding-top:8px;font-weight:bold;font-size:1.1em;color:#fff;text-shadow:0 1px 3px rgba(0,0,0,.5)}.label{font-size:.75em;color:#aaa;text-align:center;line-height:1.3}.type-tag{font-size:.65em;padding:2px 6px;border-radius:3px;margin-top:3px;font-weight:bold}.stats{margin-top:25px;background:#151530;border:1px solid #333;border-radius:8px;padding:15px 25px;font-size:.9em;line-height:1.8;max-width:500px}.highlight{color:#f0c040;font-weight:bold}</style></head><body><h1>Self-Loop Bottleneck</h1><p class='sub'>Permitted self-loops at each consonant interval</p><div class='chart' id='chart'></div><div class='stats'><b>The Bottleneck Theorem:</b><br>Perfect consonances (unison, fifth): <span class='highlight'>1 self-loop</span> each — only the identity.<br>Imperfect consonances (3rds, 6ths): <span class='highlight'>12 self-loops</span> each — all parallel motions allowed.<br>Ratio: <span class='highlight'>1 : 12</span> — the maximum possible asymmetry.</div><script>const data=[{id:0,name:'Unison',short:'P1',type:'perfect',loops:1},{id:3,name:'Minor 3rd',short:'m3',type:'imperfect',loops:12},{id:4,name:'Major 3rd',short:'M3',type:'imperfect',loops:12},{id:7,name:'Perf. 5th',short:'P5',type:'perfect',loops:1},{id:8,name:'Minor 6th',short:'m6',type:'imperfect',loops:12},{id:9,name:'Major 6th',short:'M6',type:'imperfect',loops:12}];const chart=document.getElementById('chart');const maxH=280;data.forEach((d,i)=>{const g=document.createElement('div');g.className='bar-group';const bar=document.createElement('div');bar.className='bar';bar.style.height='0px';bar.style.background=d.type==='perfect'?'linear-gradient(180deg,#f0c040,#c08020)':'linear-gradient(180deg,#4090f0,#2060c0)';bar.textContent=d.loops;const label=document.createElement('div');label.className='label';label.innerHTML=`${d.name}<br>(${d.short})`;const tag=document.createElement('div');tag.className='type-tag';tag.style.background=d.type==='perfect'?'#604010':'#103060';tag.style.color=d.type==='perfect'?'#f0c040':'#4090f0';tag.textContent=d.type.toUpperCase();g.appendChild(bar);g.appendChild(label);g.appendChild(tag);chart.appendChild(g);setTimeout(()=>{bar.style.height=(d.loops/12*maxH)+'px'},100+i*150)})</script></body></html>"
