      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Voice-Swap Asymmetry</title><style>*{margin:0;padding:0;box-sizing:border-box}body{background:#0a0a1a;color:#e0e0e0;font-family:'Segoe UI',system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;padding:25px}h1{font-size:1.4em;color:#f0c040;margin-bottom:5px}p.sub{color:#888;font-size:.85em;margin-bottom:20px}canvas{cursor:pointer;border-radius:50%}.info-box{background:#151530;border:1px solid #333;border-radius:8px;padding:15px 20px;margin-top:15px;max-width:520px;font-size:.85em;line-height:1.6;min-height:80px}.hl{color:#f0c040;font-weight:bold}.err{color:#ff6060;font-weight:bold}.ok{color:#60ff90;font-weight:bold}</style></head><body><h1>Voice-Swap Asymmetry on ℤ/12ℤ</h1><p class='sub'>Click any interval to see the negation involution i ↦ −i mod 12</p><canvas id='c' width='460' height='460'></canvas><div class='info-box' id='info'>Click an interval on the circle to explore the involution.<br>Consonant intervals are shown in <span style='color:#4090f0'>blue</span> (imperfect) or <span style='color:#f0c040'>gold</span> (perfect).<br>Dissonant intervals are shown in <span style='color:#555'>gray</span>.</div><script>const canvas=document.getElementById('c'),ctx=canvas.getContext('2d'),info=document.getElementById('info');const W=460,H=460,CX=W/2,CY=H/2,R=180;const consonant=new Set([0,3,4,7,8,9]),perfect=new Set([0,7]);const names=['P1','m2','M2','m3','M3','P4','A4/d5','P5','m6','M6','m7','M7'];const fullNames=['Unison','Minor 2nd','Major 2nd','Minor 3rd','Major 3rd','Perfect 4th','Tritone','Perfect 5th','Minor 6th','Major 6th','Minor 7th','Major 7th'];let selected=null,hovered=null;function posOf(i){const a=i*Math.PI*2/12-Math.PI/2;return[CX+R*Math.cos(a),CY+R*Math.sin(a)]}function colorOf(i){if(perfect.has(i))return'#f0c040';if(consonant.has(i))return'#4090f0';return'#555'}function draw(){ctx.clearRect(0,0,W,H);ctx.beginPath();ctx.arc(CX,CY,R,0,Math.PI*2);ctx.strokeStyle='#222';ctx.lineWidth=1;ctx.stroke();if(selected!==null){const neg=(12-selected)%12;const[x1,y1]=posOf(selected),[x2,y2]=posOf(neg);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);const preserved=consonant.has(selected)&&consonant.has(neg);ctx.strokeStyle=preserved?'rgba(96,255,144,0.4)':'rgba(255,96,96,0.4)';ctx.lineWidth=3;ctx.setLineDash([8,6]);ctx.stroke();ctx.setLineDash([])}for(let i=0;i<12;i++){const[x,y]=posOf(i);const isSelected=i===selected;const isNeg=selected!==null&&i===(12-selected)%12;const isHov=i===hovered;const r=isSelected||isNeg?22:isHov?20:16;if(isSelected){ctx.beginPath();ctx.arc(x,y,r+8,0,Math.PI*2);ctx.fillStyle='rgba(240,192,64,0.15)';ctx.fill()}if(isNeg){ctx.beginPath();ctx.arc(x,y,r+8,0,Math.PI*2);const neg=(12-selected)%12;const preserved=consonant.has(selected)&&consonant.has(neg);ctx.fillStyle=preserved?'rgba(96,255,144,0.12)':'rgba(255,96,96,0.12)';ctx.fill()}ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=colorOf(i);ctx.globalAlpha=isSelected||isNeg||isHov?1:.6;ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=isSelected?'#fff':isNeg?'#ff8':'#333';ctx.lineWidth=isSelected||isNeg?2.5:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font=(isSelected||isNeg)?'bold 12px sans-serif':'11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[i],x,y)}requestAnimationFrame(draw)}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;hovered=null;for(let i=0;i<12;i++){const[x,y]=posOf(i);if((mx-x)**2+(my-y)**2<400)hovered=i}});canvas.addEventListener('click',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;for(let i=0;i<12;i++){const[x,y]=posOf(i);if((mx-x)**2+(my-y)**2<400){selected=i;const neg=(12-i)%12;const srcCon=consonant.has(i),tgtCon=consonant.has(neg);const srcType=perfect.has(i)?'perfect':consonant.has(i)?'imperfect':'dissonant';const tgtType=perfect.has(neg)?'perfect':consonant.has(neg)?'imperfect':'dissonant';let html=`<b>${fullNames[i]}</b> (${i}) → <b>−${i} = ${neg}</b> → <b>${fullNames[neg]}</b><br>`;html+=`Source: <span style='color:${colorOf(i)}'>${srcType}</span> | `;html+=`Target: <span style='color:${colorOf(neg)}'>${tgtType}</span><br>`;if(srcCon&&tgtCon)html+=`<span class='ok'>✓ Consonance PRESERVED under voice swap.</span>`;else if(srcCon&&!tgtCon)html+=`<span class='err'>✗ Consonance BROKEN! The ${fullNames[i]} is consonant but the ${fullNames[neg]} is dissonant.</span><br>This is the voice-swap asymmetry: the bass voice is privileged.`;else if(!srcCon&&tgtCon)html+=`<span class='hl'>Dissonance becomes consonance under swap.</span>`;else html+=`Both dissonant — swap is neutral.`;info.innerHTML=html;break}}});draw()</script></body></html>"
