theorem babel_diameter_achieved {A L : ℕ} (hA : 2 ≤ A) (hL : 1 ≤ L) :
    ∃ v w : Volume A L, hammingDist v w = L := by
      refine' ⟨ fun _ => ⟨ 0, by linarith ⟩, fun _ => ⟨ 1, by linarith ⟩, _ ⟩;
      unfold hammingDist; aesop;

/-! ## Volume Cardinality -/


theorem volume_card (A L : ℕ) : Fintype.card (Volume A L) = A ^ L := by
  simp [Fintype.card_fin]

/-! ## Coding-Theoretic Bounds -/

/-
**Singleton Bound**: A code with minimum distance `d` has at most `A^(L - d + 1)` codewords.
-/

theorem hamming_bound {A L : ℕ} (hA : 1 ≤ A) (C : BabelCode A L)
    (t : ℕ) (ht : 2 * t + 1 ≤ C.minDist) (htL : t ≤ L) :
    C.codewords.card * (∑ i ∈ Finset.range (t + 1), L.choose i * (A - 1) ^ i) ≤ A ^ L := by
      -- Each ball has size $\sum_{i=0}^t \binom{L}{i}(A-1)^i$.
      have h_ball_size : ∀ v ∈ C.codewords, (Finset.filter (fun w => hammingDist v w ≤ t) Finset.univ).card = ∑ i ∈ Finset.range (t + 1), Nat.choose L i * (A - 1) ^ i := by
        intro v hv;
        -- For each $i \leq t$, the number of volumes that differ from $v$ in exactly $i$ positions is $\binom{L}{i} (A-1)^i$.
