-hovered)%12;const p1=getPos(hovered),p2=getPos(neg);ctx.beginPath();ctx.moveTo(p1.x,p1.y);ctx.lineTo(p2.x,p2.y);ctx.strokeStyle=consonant.has(neg)?'rgba(16,185,129,0.5)':'rgba(239,68,68,0.5)';ctx.lineWidth=3;ctx.setLineDash([8,4]);ctx.stroke();ctx.setLineDash([]);const mx=(p1.x+p2.x)/2,my=(p1.y+p2.y)/2;ctx.fillStyle='#888';ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillText('σ',mx-15,my-5)}for(let i=0;i<12;i++){const{x,y}=getPos(i);const isCons=consonant.has(i);const isPerf=perfect.has(i);const isHov=hovered===i;const isNeg=hovered!==null&&(12-hovered)%12===i;const r=isHov||isNeg?24:18;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);if(isHov){ctx.fillStyle='#10b981';ctx.strokeStyle='#fff';ctx.lineWidth=3}else if(isNeg){ctx.fillStyle=isCons?'#10b981':'#ef4444';ctx.strokeStyle='#fff';ctx.lineWidth=3}else{ctx.fillStyle=isCons?(isPerf?'#f59e0b44':'#6366f144'):'#33333344';ctx.strokeStyle=isCons?(isPerf?'#f59e0b':'#6366f1'):'#555';ctx.lineWidth=1.5}ctx.fill();ctx.stroke();ctx.fillStyle=isHov||isNeg?'#fff':(isCons?'#ddd':'#777');ctx.font=(isHov||isNeg)?'bold 12px sans-serif':'11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[i],x,y);ctx.fillStyle='#666';ctx.font='10px sans-serif';const lx=cx+(R+30)*Math.cos(-Math.PI/2+i*2*Math.PI/12);const ly=cy+(R+30)*Math.sin(-Math.PI/2+i*2*Math.PI/12);ctx.fillText(i,lx,ly)}ctx.fillStyle='#555';ctx.font='12px sans-serif';ctx.textAlign='center';ctx.fillText('ℤ/12ℤ Chromatic Circle',cx,cy)}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;let best=null,bestD=40;for(let i=0;i<12;i++){const p=getPos(i);const d=Math.hypot(mx-p.x,my-p.y);if(d<bestD){bestD=d;best=i}}if(best!==hovered){hovered=best;draw();const det=document.getElementById('detail');if(hovered!==null){const neg=(12-hovered)%12;const srcCons=consonant.has(hovered);const tgtCons=consonant.has(neg);const srcTag=srcCons?(perfect.has(hovered)?'<span class=\"tag 