d++){const bound=Math.pow(A,L-d+1),frac=(bound/n).toExponential(2);stbl.innerHTML+=`<tr><td>${d}</td><td>${bound}</td><td>${frac}</td></tr>`}}function getPos(i){if(A===2&&L<=4){const bits=vols[i];let x=0,y=0,z=0;if(L>=1)x=bits[0]*2-1;if(L>=2)y=bits[1]*2-1;if(L>=3)z=bits[2]*2-1;if(L>=4){x+=(bits[3]*2-1)*.3;y+=(bits[3]*2-1)*.3}return[x,y,z]}const t=i/vols.length*Math.PI*2;const r=1+.3*Math.sin(i*3.7);return[r*Math.cos(t),r*Math.sin(t),.5*Math.sin(i*2.3)]}function project(x,y,z,a){const ca=Math.cos(a),sa=Math.sin(a);const rx=x*ca-z*sa,rz=x*sa+z*ca;const sc=200/(3+rz*.5);return[230+rx*sc,200+y*sc*-.9,rz]}function draw(){const a=angle*Math.PI/180;ctx.clearRect(0,0,c.width,c.height);const proj=vols.map((_,i)=>{const[x,y,z]=getPos(i);return project(x,y,z,a)});const nbrs=new Set();edges.forEach(([i,j])=>{if(i===selected||j===selected)nbrs.add(i===selected?j:i)});edges.forEach(([i,j])=>{const isNbr=i===selected||j===selected;ctx.beginPath();ctx.moveTo(proj[i][0],proj[i][1]);ctx.lineTo(proj[j][0],proj[j][1]);ctx.strokeStyle=isNbr?'rgba(126,184,255,0.7)':'rgba(100,100,140,0.2)';ctx.lineWidth=isNbr?2.5:1;ctx.stroke()});const order=[...Array(vols.length).keys()].sort((a,b)=>proj[a][2]-proj[b][2]);order.forEach(i=>{const[px,py]=proj[i];const isSelected=i===selected;const isNbr=nbrs.has(i);const r=isSelected?12:isNbr?9:6;ctx.beginPath();ctx.arc(px,py,r,0,Math.PI*2);if(isSelected){ctx.fillStyle='#ffcc00';ctx.shadowColor='#ffcc00';ctx.shadowBlur=15}else if(isNbr){ctx.fillStyle='#7eb8ff';ctx.shadowColor='#7eb8ff';ctx.shadowBlur=8}else{ctx.fillStyle='#4a4a6a';ctx.shadowBlur=0}ctx.fill();ctx.shadowBlur=0;if(vols.length<=32){ctx.fillStyle=isSelected?'#000':'#fff';ctx.font=(isSelected?'bold ':'')+`${isSelected?10:8}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(vols[i].join(''),px,py)}});const nbrList=[...nbrs].map(j=>vols[j].join('')).join(', ');info.innerHTML=`<b>Volume:</b> <span class=\"highlight\">${vols[selected].join('')}</span><br><b>Neighbors (dist=1):</b> ${nbrList}<br><b>Neighbor count:</b> ${nbrs.size} = L×(A−1) = ${L}×${A-1} ✓<br><b>Max distance from here:</b> ${Math.max(...vols.map((_,j)=>hd(selected,j)))}`}sel.onchange=()=>{selected=+sel.value;draw()};rot.oninput=()=>{angle=+rot.value;draw()};c.onclick=(e)=>{const rect=c.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;const a=angle*Math.PI/180;let best=-1,bestD=Infinity;vols.forEach((_,i)=>{const[x,y,z]=getPos(i);const[px,py]=project(x,y,z,a);const d=Math.hypot(px-mx,py-my);if(d<bestD){bestD=d;best=i}});if(bestD<20){selected=best;sel.value=best;draw()}};alphaS.onchange=init;lenS.onchange=init;init()</script></body></html>"
