        print(f"  {names[i]} -> {names[j]}: VL({vl1.bass}, {vl1.soprano})")
        print(f"  {names[j]} -> {names[k]}: VL({vl2.bass}, {vl2.soprano})")
        comp = vl1.compose(vl2)
        print(f"  Composition: VL({comp.bass}, {comp.soprano}) — FORBIDDEN")

