theorem bch_defect_zero_of_commute (h₁ h₂ : 𝔸) (hcomm : Commute h₁ h₂) :
    bchDefect h₁ h₂ = 0 := by
  simp [bchDefect, NormedSpace.exp_add_of_commute hcomm]

/-- **Self-Inverse Defect**: bchDefect(h, -h) = 0. -/

theorem qeml_channel_compose_comm (h₁ h₂ : 𝔸) (hcomm : Commute h₁ h₂) (ρ : 𝔸) :
    qemlChannel h₁ (qemlChannel h₂ ρ) = qemlChannel (h₁ + h₂) ρ := by
  have h_split_exp : NormedSpace.exp (h₁ + h₂) = NormedSpace.exp h₁ * NormedSpace.exp h₂ := by
    exact?;
  have h_split_exp_neg : NormedSpace.exp (-(h₁ + h₂)) = NormedSpace.exp (-h₂) * NormedSpace.exp (-h₁) := by
    have := NormedSpace.exp_add_of_commute ( show Commute ( -h₂ ) ( -h₁ ) from by simp [ hcomm.symm ] ) ; simp_all +decide [ ← mul_assoc ] ;
  unfold qemlChannel; simp_all +decide [ mul_assoc ] ;

/-! ## Neuron Properties -/

/-- **Neuron at Zero**: qemlNeuron 0 t ρ = ρ + t • 1. -/

theorem qeml_dist_triangle (g₁ g₂ g₃ : QuantumEMLGate 𝔸) :
    qemlDist g₁ g₃ ≤ qemlDist g₁ g₂ + qemlDist g₂ g₃ := by
  simp only [qemlDist]
  calc ‖qemlEval g₁ - qemlEval g₃‖
      = ‖(qemlEval g₁ - qemlEval g₂) + (qemlEval g₂ - qemlEval g₃)‖ := by
        congr 1; abel
    _ ≤ ‖qemlEval g₁ - qemlEval g₂‖ + ‖qemlEval g₂ - qemlEval g₃‖ :=
        norm_add_le _ _

/-! ## Quantum-Classical Bridge -/

/-- **Real Commutative Reduction**: In ℝ, QEML gate collapses to exp(h₁+h₂). -/

theorem qeml_diagonal_spectral (a₁ a₂ b₁ b₂ : ℂ) :
    let D₁ := Matrix.diagonal ![a₁, a₂]
    let D₂ := Matrix.diagonal ![b₁, b₂]
    NormedSpace.exp D₁ * NormedSpace.exp D₂ =
    Matrix.diagonal ![NormedSpace.exp a₁ * NormedSpace.exp b₁,
                       NormedSpace.exp a₂ * NormedSpace.exp b₂] := by
  convert congr_arg₂ ( · * · ) ?_ ?_;
  rotate_left;
  exact Matrix.diagonal ![Complex.exp a₁, Complex.exp a₂];
  exact Matrix.diagonal ![Complex.exp b₁, Complex.exp b₂];
  · convert ( Matrix.exp_diagonal _ );
    all_goals try infer_instance;
    ext i;
    fin_cases i <;> norm_num [ Complex.exp_eq_exp_ℂ, NormedSpace.exp_eq_tsum ];
  · convert ( Matrix.exp_diagonal _ ) using 1;
    all_goals try infer_instance;
    congr! 1;
    ext i; fin_cases i <;> norm_num [ Complex.exp_eq_exp_ℂ, NormedSpace.exp_eq_tsum ] ;
  · norm_num [ Complex.exp_eq_exp_ℂ, NormedSpace.exp_eq_tsum_div ]

/-- **Gate Composition Law**: When the log parameter of one gate commutes
    with the exp parameter of the next, we get a predictable product. -/

