      "html": "<div style='font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; background: #f8f9fa; border-radius: 12px;'><h2 style='color: #2c3e50; text-align: center;'>Proof Density Phase Transition Explorer</h2><p style='color: #555; text-align: center;'>Adjust parameters to see how provability density transitions from complete to incomplete.</p><div style='display: flex; gap: 20px; margin: 15px 0; flex-wrap: wrap;'><div style='flex: 1; min-width: 200px;'><label style='font-weight: bold; color: #34495e;'>Alphabet Size (b): <span id='bVal'>2</span></label><br><input type='range' id='bSlider' min='2' max='10' value='2' style='width: 100%;'></div><div style='flex: 1; min-width: 200px;'><label style='font-weight: bold; color: #34495e;'>Threshold (n_c): <span id='ncVal'>5</span></label><br><input type='range' id='ncSlider' min='2' max='15' value='5' style='width: 100%;'></div><div style='flex: 1; min-width: 200px;'><label style='font-weight: bold; color: #34495e;'>Proof Growth: <span id='modeVal'>Linear (1/2)</span></label><br><select id='modeSelect' style='width: 100%; padding: 5px; border-radius: 4px;'><option value='linear'>Linear (slope 1/2)</option><option value='sqrt'>Square Root</option><option value='log'>Logarithmic</option><option value='const'>Constant</option></select></div></div><canvas id='densityCanvas' width='760' height='300' style='background: white; border: 1px solid #ddd; border-radius: 8px; display: block; margin: 10px auto;'></canvas><canvas id='gapCanvas' width='760' height='250' style='background: white; border: 1px solid #ddd; border-radius: 8px; display: block; margin: 10px auto;'></canvas><div id='stats' style='background: white; padding: 15px; border-radius: 8px; margin-top: 10px; border: 1px solid #ddd;'></div><script>(function(){const bS=document.getElementById('bSlider'),ncS=document.getElementById('ncSlider'),mS=document.getElementById('modeSelect'),bV=document.getElementById('bVal'),ncV=document.getElementById('ncVal'),mV=document.getElementById('modeVal'),dc=document.getElementById('densityCanvas'),gc=document.getElementById('gapCanvas'),st=document.getElementById('stats');const dctx=dc.getContext('2d'),gctx=gc.getContext('2d');function proofBound(n,b,nc,mode){if(n<=nc)return n;const d=n-nc;switch(mode){case'linear':return nc+Math.floor(d/2);case'sqrt':return nc+Math.floor(Math.sqrt(d));case'log':return nc+Math.floor(2*Math.log2(Math.max(1,d)));case'const':return nc+2;default:return nc+Math.floor(d/2);}}function draw(){const b=parseInt(bS.value),nc=parseInt(ncS.value),mode=mS.value;bV.textContent=b;ncV.textContent=nc;mV.textContent=mS.options[mS.selectedIndex].text;const maxN=30,densities=[],gaps=[],dims=[];for(let n=1;n<=maxN;n++){const pb=proofBound(n,b,nc,mode);const logDensity=Math.min(0,(pb-n)*Math.log(b));densities.push({n,density:Math.exp(logDensity),logD:logDensity});const gap=Math.max(0,Math.pow(b,n)-Math.pow(b,pb));gaps.push({n,gap:gap,logGap:gap>0?Math.log10(gap):0});dims.push({n,dim:pb/n});}dctx.clearRect(0,0,dc.width,dc.height);const pad={l:60,r:20,t:30,b:40};const pw=dc.width-pad.l-pad.r,ph=dc.height-pad.t-pad.b;dctx.fillStyle='#2c3e50';dctx.font='bold 13px Arial';dctx.textAlign='center';dctx.fillText('Provability Density ρ(n) — Log Scale',dc.width/2,18);const minLog=Math.min(...densities.map(d=>d.logD),-1);const maxLog=0;dctx.strokeStyle='#ddd';dctx.lineWidth=0.5;for(let i=0;i<=5;i++){const y=pad.t+ph*(i/5);dctx.beginPath();dctx.moveTo(pad.l,y);dctx.lineTo(pad.l+pw,y);dctx.stroke();}dctx.strokeStyle='#e74c3c';dctx.lineWidth=1;dctx.setLineDash([5,5]);const ncX=pad.l+((nc-1)/(maxN-1))*pw;dctx.beginPath();dctx.moveTo(ncX,pad.t);dctx.lineTo(ncX,pad.t+ph);dctx.stroke();dctx.setLineDash([]);dctx.fillStyle='#e74c3c';dctx.font='11px Arial';dctx.fillText('n_c='+nc,ncX,pad.t+ph+15);dctx.strokeStyle='#3498db';dctx.lineWidth=2.5;dctx.beginPath();for(let i=0;i<densities.length;i++){const x=pad.l+(i/(maxN-1))*pw;const logRange=maxLog-minLog||1;const y=pad.t+ph*(1-(densities[i].logD-minLog)/logRange);if(i===0)dctx.moveTo(x,y);else dctx.lineTo(x,y);}dctx.stroke();for(let i=0;i<densities.length;i++){const x=pad.l+(i/(maxN-1))*pw;const logRange=maxLog-minLog||1;const y=pad.t+ph*(1-(densities[i].logD-minLog)/logRange);dctx.beginPath();dctx.arc(x,y,3,0,2*Math.PI);dctx.fillStyle='#3498db';dctx.fill();}dctx.fillStyle='#555';dctx.font='10px Arial';dctx.textAlign='center';for(let n=5;n<=maxN;n+=5){const x=pad.l+((n-1)/(maxN-1))*pw;dctx.fillText(n,x,pad.t+ph+30);}dctx.textAlign='right';for(let i=0;i<=4;i++){const val=minLog+(maxLog-minLog)*(1-i/4);const y=pad.t+ph*(i/4);dctx.fillText(val.toFixed(1),pad.l-5,y+4);}gctx.clearRect(0,0,gc.width,gc.height);gctx.fillStyle='#2c3e50';gctx.font='bold 13px Arial';gctx.textAlign='center';gctx.fillText('Unprovability Gap G(n) — Log₁₀ Scale',gc.width/2,18);const gph=gc.height-pad.t-pad.b;const maxLogGap=Math.max(...gaps.map(g=>g.logGap),1);gctx.strokeStyle='#ddd';gctx.lineWidth=0.5;for(let i=0;i<=4;i++){const y=pad.t+gph*(i/4);gctx.beginPath();gctx.moveTo(pad.l,y);gctx.lineTo(pad.l+pw,y);gctx.stroke();}gctx.strokeStyle='#e67e22';gctx.lineWidth=2.5;gctx.beginPath();let started=false;for(let i=0;i<gaps.length;i++){if(gaps[i].gap>0){const x=pad.l+(i/(maxN-1))*pw;const y=pad.t+gph*(1-gaps[i].logGap/maxLogGap);if(!started){gctx.moveTo(x,y);started=true;}else gctx.lineTo(x,y);}}gctx.stroke();gctx.fillStyle='#555';gctx.font='10px Arial';gctx.textAlign='center';for(let n=5;n<=maxN;n+=5){const x=pad.l+((n-1)/(maxN-1))*pw;gctx.fillText(n,x,pad.t+gph+30);}const firstInc=densities.findIndex(d=>d.density<1);const lastDensity=densities[densities.length-1].density;const totalGap=gaps.reduce((s,g)=>s+g.gap,0);st.innerHTML='<div style=\"display:flex;gap:20px;flex-wrap:wrap;\"><div style=\"flex:1;min-width:150px;\"><strong style=\"color:#2c3e50;\">Phase Transition</strong><br>Threshold: n_c = '+nc+'<br>First incomplete: n = '+(firstInc>=0?firstInc+1:'none')+'</div><div style=\"flex:1;min-width:150px;\"><strong style=\"color:#2c3e50;\">Density at n='+maxN+'</strong><br>ρ('+maxN+') = '+lastDensity.toExponential(3)+'<br>Proof dim: '+(proofBound(maxN,b,nc,mode)/maxN).toFixed(3)+'</div><div style=\"flex:1;min-width:150px;\"><strong style=\"color:#2c3e50;\">Key Insight</strong><br>'+(lastDensity<0.01?'Severe incompleteness: <1% provable':'Moderate density: system still fairly complete')+'</div></div>';}bS.addEventListener('input',draw);ncS.addEventListener('input',draw);mS.addEventListener('change',draw);draw();})()</script></div>"
