      "html": "<div style='font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto; padding: 20px; background: linear-gradient(135deg, #1a1a2e, #16213e); border-radius: 12px; color: #eee;'><h2 style='text-align: center; color: #e94560;'>Gap Amplification Cascade</h2><p style='text-align: center; color: #aaa;'>Watch one unprovable statement cascade into exponentially many</p><div style='display: flex; gap: 15px; margin: 15px 0;'><div style='flex:1;'><label>Alphabet (b): <span id='gB'>2</span></label><br><input type='range' id='gBS' min='2' max='5' value='2' style='width:100%;'></div><div style='flex:1;'><label>Start Level: <span id='gN'>6</span></label><br><input type='range' id='gNS' min='3' max='15' value='6' style='width:100%;'></div><div style='flex:1;'><button id='gRun' style='width:100%;padding:10px;background:#e94560;color:white;border:none;border-radius:6px;cursor:pointer;font-size:14px;margin-top:15px;'>▶ Animate</button></div></div><canvas id='gC' width='660' height='350' style='background:#0f3460;border-radius:8px;display:block;margin:10px auto;'></canvas><div id='gInfo' style='background:#16213e;padding:12px;border-radius:8px;border:1px solid #333;margin-top:10px;'></div><script>(function(){const bS=document.getElementById('gBS'),nS=document.getElementById('gNS'),btn=document.getElementById('gRun'),cv=document.getElementById('gC'),info=document.getElementById('gInfo');const ctx=cv.getContext('2d');let animId=null,step=0,maxSteps=15;function draw(b,n0,curStep){ctx.clearRect(0,0,cv.width,cv.height);const pad={l:50,r:20,t:20,b:40};const pw=cv.width-pad.l-pad.r,ph=cv.height-pad.t-pad.b;const maxK=maxSteps;const maxLogGap=maxK*Math.log10(b);ctx.strokeStyle='#1a1a4e';ctx.lineWidth=0.5;for(let i=0;i<=5;i++){const y=pad.t+ph*(i/5);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(pad.l+pw,y);ctx.stroke();}ctx.strokeStyle='#e94560';ctx.lineWidth=3;ctx.beginPath();for(let k=0;k<=Math.min(curStep,maxK);k++){const x=pad.l+(k/maxK)*pw;const logGap=k*Math.log10(b);const y=pad.t+ph*(1-logGap/(maxLogGap||1));if(k===0)ctx.moveTo(x,y);else ctx.lineTo(x,y);}ctx.stroke();for(let k=0;k<=Math.min(curStep,maxK);k++){const x=pad.l+(k/maxK)*pw;const logGap=k*Math.log10(b);const y=pad.t+ph*(1-logGap/(maxLogGap||1));const r=Math.min(8,4+k*0.3);ctx.beginPath();ctx.arc(x,y,r,0,2*Math.PI);const alpha=Math.min(1,0.3+k*0.05);ctx.fillStyle=`rgba(233,69,96,${alpha})`;ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=1;ctx.stroke();if(k<=curStep&&k%3===0){ctx.fillStyle='#fff';ctx.font='10px monospace';ctx.textAlign='center';ctx.fillText('b^'+k+'='+Math.pow(b,k),x,y-r-5);}}ctx.fillStyle='#aaa';ctx.font='11px Arial';ctx.textAlign='center';for(let k=0;k<=maxK;k+=3){const x=pad.l+(k/maxK)*pw;ctx.fillText('n='+(n0+k),x,pad.t+ph+25);}ctx.textAlign='right';ctx.fillStyle='#aaa';for(let i=0;i<=4;i++){const val=maxLogGap*(1-i/4);const y=pad.t+ph*(i/4);ctx.fillText('10^'+val.toFixed(0),pad.l-5,y+4);}const gap=Math.pow(b,Math.min(curStep,maxK));info.innerHTML='<span style=\"color:#e94560;font-size:18px;\">Level '+(n0+Math.min(curStep,maxK))+'</span>: at least <strong style=\"color:#fff;font-size:16px;\">'+gap.toLocaleString()+'</strong> unprovable statements (b^'+Math.min(curStep,maxK)+' = '+b+'^'+Math.min(curStep,maxK)+')';}function animate(){const b=parseInt(bS.value),n0=parseInt(nS.value);document.getElementById('gB').textContent=b;document.getElementById('gN').textContent=n0;if(step<=maxSteps){draw(b,n0,step);step++;animId=setTimeout(animate,300);}else{draw(b,n0,maxSteps);}}btn.addEventListener('click',function(){if(animId)clearTimeout(animId);step=0;animate();});bS.addEventListener('input',function(){document.getElementById('gB').textContent=bS.value;if(animId)clearTimeout(animId);step=0;draw(parseInt(bS.value),parseInt(nS.value),0);});nS.addEventListener('input',function(){document.getElementById('gN').textContent=nS.value;if(animId)clearTimeout(animId);step=0;draw(parseInt(bS.value),parseInt(nS.value),0);});draw(2,6,0);})()</script></div>"
