eriodSlider=document.getElementById('periodSlider'),ruleNum=document.getElementById('ruleNum'),periodNum=document.getElementById('periodNum'),revStatus=document.getElementById('revStatus'),ruleTable=document.getElementById('ruleTable'),orbitsDiv=document.getElementById('orbits'),canvas=document.getElementById('caCanvas'),ctx=canvas.getContext('2d');function getRule(num){let r={};for(let i=0;i<8;i++){let nb=[(i>>2)&1,(i>>1)&1,i&1];r[nb.join('')]=((num>>i)&1)}return r}function applyRule(rule,config){let n=config.length,res=[];for(let i=0;i<n;i++){let nb=''+config[(i-1+n)%n]+config[i]+config[(i+1)%n];res.push(rule[nb])}return res}function isReversible(ruleNum,period){let rule=getRule(ruleNum),configs=[];for(let i=0;i<(1<<period);i++){let c=[];for(let j=0;j<period;j++)c.push((i>>j)&1);configs.push(c)}let images=new Set();for(let c of configs){let img=applyRule(rule,c).join(',');if(images.has(img))return false;images.add(img)}return true}function shiftConfig(c){let n=c.length;return c.map((_,i)=>c[(i+1)%n])}function computeOrbits(period){let configs=[];for(let i=0;i<(1<<period);i++){let c=[];for(let j=0;j<period;j++)c.push((i>>j)&1);configs.push(c)}let visited=new Set(),orbits=[];for(let c of configs){let key=c.join(',');if(visited.has(key))continue;let orbit=[c.slice()],cur=c.slice();for(let k=0;k<period-1;k++){cur=shiftConfig(cur);let ck=cur.join(',');if(visited.has(ck))break;orbit.push(cur.slice())}for(let o of orbit)visited.add(o.join(','));orbits.push(orbit)}return orbits}function factorial(n){let r=1;for(let i=2;i<=n;i++)r*=i;return r}function update(){let rn=parseInt(ruleSlider.value),p=parseInt(periodSlider.value);ruleNum.textContent=rn;periodNum.textContent=p;let rule=getRule(rn),rev=isReversible(rn,p);revStatus.textContent=rev?'✅ REVERSIBLE on period '+p:'❌ NOT REVERSIBLE on period '+p;revStatus.style.background=rev?'#d5f5e3':'#fadbd8';let tableHTML='<table style=\"border-collapse:collapse\">';tableHTML+='<tr><th style=\"padding:2px 6px;border:1px solid #ccc\">In</th><th style=\"padding:2px 6px;border:1px solid #ccc\">Out</th></tr>';for(let i=7;i>=0;i--){let nb=((i>>2)&1)+''+((i>>1)&1)+''+(i&1);tableHTML+='<tr><td style=\"padding:2px 6px;border:1px solid #ccc\">'+nb+'</td><td style=\"padding:2px 6px;border:1px solid #ccc;text-align:center\">'+(rule[nb])+'</td></tr>'}tableHTML+='</table>';ruleTable.innerHTML=tableHTML;let initConfig=[];for(let i=0;i<p;i++)initConfig.push(i===p>>1?1:0);ctx.clearRect(0,0,canvas.width,canvas.height);let cellW=Math.min(30,canvas.width/p),rows=Math.min(20,Math.floor(canvas.height/cellW)),config=initConfig;for(let t=0;t<rows;t++){for(let i=0;i<p;i++){ctx.fillStyle=config[i]?'#2c3e50':'#ecf0f1';ctx.fillRect(i*cellW,t*cellW,cellW-1,cellW-1)}config=applyRule(rule,config)}let orbits=computeOrbits(p),sizeCount={};for(let o of orbits){let s=o.length;sizeCount[s]=(sizeCount[s]||0)+1}let html='<b>'+orbits.length+' necklaces:</b><br>';let groupSize=1;for(let[d,cd]of Object.entries(sizeCount)){d=parseInt(d);cd=parseInt(cd);html+='  '+cd+' orbit(s) of size '+d+'<br>';groupSize*=factorial(cd)*Math.pow(d,cd)}html+='<br><b>|Rev('+p+')| = '+groupSize+'</b>';html+='<br><b>|S<sub>'+Math.pow(2,p)+'</sub>| = '+factorial(Math.pow(2,p)).toExponential(2)+'</b>';orbitsDiv.innerHTML=html}ruleSlider.addEventListener('input',update);periodSlider.addEventListener('input',update);document.getElementById('runBtn').addEventListener('click',update);update();</script>"
