      "html": "<div style='font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; background: #1a1a2e; color: #eee; border-radius: 10px;'><h2 style='text-align: center; color: #e94560;'>🔍 Reversibility Sieve</h2><p style='text-align: center; color: #aaa;'>Watch rules get eliminated as the period increases</p><div style='text-align: center; margin: 15px 0;'><button id='sieveBtn' style='padding: 10px 30px; background: #e94560; color: white; border: none; border-radius: 5px; cursor: pointer; font-size: 16px;'>▶ Run Sieve</button><span id='sieveStatus' style='margin-left: 15px; font-size: 14px;'></span></div><canvas id='sieveCanvas' width='770' height='350' style='border: 1px solid #333; background: #16213e; border-radius: 5px; display: block; margin: 0 auto;'></canvas><div id='survivors' style='margin-top: 10px; font-family: monospace; color: #0f3460; background: #e2e8f0; padding: 10px; border-radius: 5px;'></div></div><script>(function(){const canvas=document.getElementById('sieveCanvas'),ctx=canvas.getContext('2d'),btn=document.getElementById('sieveBtn'),status=document.getElementById('sieveStatus'),surv=document.getElementById('survivors');function getRule(num){let r={};for(let i=0;i<8;i++){let nb=[(i>>2)&1,(i>>1)&1,i&1];r[nb.join('')]=((num>>i)&1)}return r}function applyRule(rule,config){let n=config.length,res=[];for(let i=0;i<n;i++){let nb=''+config[(i-1+n)%n]+config[i]+config[(i+1)%n];res.push(rule[nb])}return res}function isRev(rn,period){let rule=getRule(rn),configs=[];for(let i=0;i<(1<<period);i++){let c=[];for(let j=0;j<period;j++)c.push((i>>j)&1);configs.push(c)}let seen=new Set();for(let c of configs){let img=applyRule(rule,c).join(',');if(seen.has(img))return false;seen.add(img)}return true}let periods=[3,4,5,6,7,8],alive=new Array(256).fill(true),step=0;function drawGrid(highlight){ctx.clearRect(0,0,canvas.width,canvas.height);let cellW=canvas.width/32,cellH=canvas.height/8;for(let r=0;r<256;r++){let x=(r%32)*cellW,y=Math.floor(r/32)*cellH;if(!alive[r]){ctx.fillStyle='#1a1a2e';ctx.fillRect(x,y,cellW-1,cellH-1)}else{let hue=120+r*0.5;ctx.fillStyle='hsl('+hue+',70%,50%)';ctx.fillRect(x,y,cellW-1,cellH-1);ctx.fillStyle='white';ctx.font='9px monospace';ctx.fillText(r,x+2,y+cellH-3)}}ctx.fillStyle='#e94560';ctx.font='14px Arial';let count=alive.filter(a=>a).length;ctx.fillText('Period ≤ '+(step>0?periods[step-1]:'—')+': '+count+' rules survive',10,canvas.height-5)}function runStep(){if(step>=periods.length){surv.innerHTML='<b>Survivors:</b> '+alive.map((a,i)=>a?i:null).filter(x=>x!==null).join(', ');status.textContent='✅ Sieve complete!';return}let p=periods[step];for(let r=0;r<256;r++){if(alive[r]&&!isRev(r,p))alive[r]=false}step++;drawGrid();let count=alive.filter(a=>a).length;status.textContent='After period '+p+': '+count+' rules';setTimeout(runStep,800)}btn.addEventListener('click',function(){alive=new Array(256).fill(true);step=0;status.textContent='Running...';surv.innerHTML='';drawGrid();setTimeout(runStep,500)});drawGrid()})();</script>"
