      "html": "<div style='font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto; padding: 20px; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); border-radius: 10px; color: white;'><h2 style='text-align: center;'>⚡ Galois Connection: Subgroups ↔ Fixed Points</h2><p style='text-align: center; opacity: 0.9;'>Larger subgroups fix fewer configurations (antitone property)</p><div style='display: flex; gap: 20px; margin-top: 20px;'><div style='flex: 1; background: rgba(255,255,255,0.1); padding: 15px; border-radius: 8px;'><h3>Subgroup Lattice</h3><svg id='galoisSVG' width='340' height='300'></svg></div><div style='flex: 1; background: rgba(255,255,255,0.1); padding: 15px; border-radius: 8px;'><h3>Fixed Configurations</h3><div id='fixedInfo' style='font-size: 13px; line-height: 1.8;'></div><div id='configGrid' style='margin-top: 10px;'></div></div></div><div style='margin-top: 15px; background: rgba(255,255,255,0.1); padding: 10px; border-radius: 8px; font-size: 12px;'><b>Theorem (Galois Antitone):</b> If H₁ ≤ H₂ then Fixed(H₂) ⊆ Fixed(H₁). Click subgroups to explore.</div></div><script>(function(){const n=3,configs=[];for(let i=0;i<8;i++){let c=[];for(let j=0;j<n;j++)c.push((i>>j)&1);configs.push(c)}function shift(c){return[c[2],c[0],c[1]]}function complement(c){return c.map(x=>1-x)}function isFixed(c,generators){for(let g of generators){let gc=g(c);if(gc.join(',')!==c.join(','))return false}return true}const subgroups=[{name:'{id}',generators:[],order:1,y:250,color:'#2ecc71'},{name:'⟨κ⟩',generators:[complement],order:2,y:170,color:'#3498db'},{name:'⟨σ⟩',generators:[shift],order:3,y:170,color:'#e67e22'},{name:'⟨σ,κ⟩',generators:[shift,complement],order:6,y:90,color:'#e74c3c'},{name:'Rev(3)',generators:[shift,complement],order:36,y:30,color:'#9b59b6'}];const edges=[[0,1],[0,2],[1,3],[2,3],[3,4]];const svg=document.getElementById('galoisSVG'),fixedInfo=document.getElementById('fixedInfo'),configGrid=document.getElementById('configGrid');function drawLattice(selected){svg.innerHTML='';for(let[a,b]of edges){let sa=subgroups[a],sb=subgroups[b];let line=document.createElementNS('http://www.w3.org/2000/svg','line');line.setAttribute('x1',170);line.setAttribute('y1',sa.y+15);line.setAttribute('x2',a===0&&b===1?100:a===0&&b===2?240:b===4?170:a===1?100:240);line.setAttribute('y2',sb.y+15);line.setAttribute('stroke','rgba(255,255,255,0.3)');line.setAttribute('stroke-width','2');svg.appendChild(line)}subgroups.forEach((s,i)=>{let x=i===0?170:i===1?100:i===2?240:i===3?170:170;let g=document.createElementNS('http://www.w3.org/2000/svg','g');g.style.cursor='pointer';g.onclick=()=>showFixed(i);let rect=document.createElementNS('http://www.w3.org/2000/svg','rect');rect.setAttribute('x',x-50);rect.setAttribute('y',s.y);rect.setAttribute('width',100);rect.setAttribute('height',30);rect.setAttribute('rx',5);rect.setAttribute('fill',i===selected?'white':s.color);rect.setAttribute('stroke','white');rect.setAttribute('stroke-width',i===selected?'3':'1');g.appendChild(rect);let text=document.createElementNS('http://www.w3.org/2000/svg','text');text.setAttribute('x',x);text.setAttribute('y',s.y+20);text.setAttribute('text-anchor','middle');text.setAttribute('fill',i===selected?s.color:'white');text.setAttribute('font-size','13');text.setAttribute('font-weight','bold');text.textContent=s.name;g.appendChild(text);svg.appendChild(g)})}function showFixed(idx){let s=subgroups[idx];let fixed=configs.filter(c=>isFixed(c,s.generators));drawLattice(idx);fixedInfo.innerHTML='<b>'+s.name+'</b> (order '+s.order+')<br>Fixes <b>'+fixed.length+'</b> out of 8 configurations:<br>';let html='';for(let c of fixed){html+='<span style=\"display:inline-block;margin:3px;padding:3px 8px;background:rgba(255,255,255,0.2);border-radius:4px;font-family:monospace\">'+c.join('')+'</span> '}fixedInfo.innerHTML+=html;configGrid.innerHTML='<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:5px\">';for(let c of configs){let isF=fixed.s