{const d=hamming(volumes[i],volumes[selected]);const isNbr=d===1;const isSel=i===selected;const isHov=i===hovered;let col='#475569',sz=5;if(isSel){col='#f59e0b';sz=10}else if(isNbr){col='#60a5fa';sz=7}else if(isHov){col='#a78bfa';sz=8}ctx.beginPath();ctx.arc(positions[i].x,positions[i].y,sz,0,2*Math.PI);ctx.fillStyle=col;ctx.fill();if(isSel||isHov||n<=32){ctx.fillStyle=isSel?'#fbbf24':isNbr?'#93c5fd':'#94a3b8';ctx.font=(isSel?'bold ':'')+'10px monospace';ctx.textAlign='center';ctx.fillText(volumes[i].join(''),positions[i].x,positions[i].y-sz-4)}}updateStats()}function updateStats(){const n=volumes.length;const deg=L*(A-1);const nbrs=volumes.filter((_,i)=>hamming(volumes[i],volumes[selected])===1).length;document.getElementById('statSize').textContent=n;document.getElementById('statDeg').textContent=deg;document.getElementById('statDiam').textContent=L;document.getElementById('statNbrs').textContent=nbrs;document.getElementById('selVol').value=volumes[selected].join('')}function rebuild(){A=+document.getElementById('alphaSelect').value;L=+document.getElementById('lenSelect').value;if(Math.pow(A,L)>256){alert('Too many volumes (max 256). Reducing L.');L=Math.floor(Math.log(256)/Math.log(A));document.getElementById('lenSelect').value=L}selected=0;genVolumes();layout();draw()}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;hovered=-1;for(let i=0;i<positions.length;i++){const dx=positions[i].x-mx,dy=positions[i].y-my;if(dx*dx+dy*dy<100){hovered=i;break}}draw()});canvas.addEventListener('click',()=>{if(hovered>=0){selected=hovered;draw()}});document.getElementById('alphaSelect').addEventListener('change',rebuild);document.getElementById('lenSelect').addEventListener('change',rebuild);rebuild()</script></body></html>"
