v class='controls'><div class='ctrl'><label>Alphabet A</label><input type='range' id='rA' min='2' max='8' value='4'><div class='v' id='dA'>4</div></div><div class='ctrl'><label>Length L</label><input type='range' id='rL' min='4' max='32' value='16'><div class='v' id='dL'>16</div></div></div><canvas id='chart' width='860' height='400'></canvas><div class='legend'><span><span class='dot' style='background:#f59e0b'></span> Singleton bound</span><span><span class='dot' style='background:#60a5fa'></span> Hamming (sphere-packing) bound</span><span><span class='dot' style='background:#475569'></span> Library size A<sup>L</sup></span></div><div class='table-wrap'><table id='tbl'><thead><tr><th>Min dist d</th><th>Singleton A<sup>L−d+1</sup></th><th>Hamming ⌊A<sup>L</sup>/|B(v,⌊(d−1)/2⌋)|⌋</th><th>Tighter bound</th></tr></thead><tbody id='tbody'></tbody></table></div><div class='theorem-box'><strong>singleton_bound:</strong> |C| ≤ A<sup>L−d+1</sup> for a BabelCode with min distance d.<br><strong>sphere_size_sum:</strong> ∑<sub>k=0</sub><sup>L</sup> C(L,k)·(A−1)<sup>k</sup> = A<sup>L</sup> — the binomial identity underlying the Hamming bound.<br><strong>babel_degree:</strong> Each volume has L·(A−1) neighbors, governing sphere sizes.</div></div><script>const cv=document.getElementById('chart'),cx=cv.getContext('2d');function comb(n,k){if(k<0||k>n)return 0;if(k===0||k===n)return 1;let r=1;for(let i=0;i<k;i++)r=r*(n-i)/(i+1);return Math.round(r)}function ballSize(A,L,r){let s=0;for(let k=0;k<=r&&k<=L;k++)s+=comb(L,k)*Math.pow(A-1,k);return s}function draw(){const A=+document.getElementById('rA').value;const L=+document.getElementById('rL').value;document.getElementById('dA').textContent=A;document.getElementById('dL').textContent=L;const libSize=Math.pow(A,L);const logLib=L*Math.log10(A);const data=[];for(let d=1;d<=L;d++){const sing=Math.pow(A,L-d+1);const logSing=(L-d+1)*Math.log10(A);const r=Math.floor((d-1)/2);const bs=ballSize(A,L,r);const ham=Math.floor(libSize/bs);const logHam=Math.log10(Math.max(ham,1));const tighter=Math.min(logSing,logHam);data.push({d,logSing,logHam:logHam,tighter})}const W=cv.width,H=cv.height,pad={l:60,r:20,t:20,b:40};const pw=W-pad.l-pad.r,ph=H-pad.t-pad.b;const maxD=L;const maxY=logLib*1.05;cx.clearRect(0,0,W,H);cx.strokeStyle='#334155';cx.lineWidth=1;cx.beginPath();for(let i=0;i<=5;i++){const y=pad.t+ph-ph*(i/5);cx.moveTo(pad.l,y);cx.lineTo(W-pad.r,y)}cx.stroke();cx.fillStyle='#64748b';cx.font='11px monospace';cx.textAlign='right';for(let i=0;i<=5;i++){const y=pad.t+ph-ph*(i/5);const val=(maxY*i/5).toFixed(1);cx.fillText('10^'+val,pad.l-6,y+4)}cx.textAlign='center';const step=Math.max(1,Math.floor(maxD/10));for(let d=1;d<=maxD;d+=step){const x=pad.l+pw*((d-1)/(maxD-1||1));cx.fillText(d.toString(),x,H-pad.b+16)}cx.fillText('Min distance d',pad.l+pw/2,H-4);cx.setLineDash([4,4]);cx.strokeStyle='#475569';cx.lineWidth=1;cx.beginPath();const libY=pad.t+ph-ph*(logLib/maxY);cx.moveTo(pad.l,libY);cx.lineTo(W-pad.r,libY);cx.stroke();cx.setLineDash([]);cx.fillStyle='#64748b';cx.fillText('A^L',W-pad.r+10,libY+4);function plotLine(pts,key,color,w){cx.strokeStyle=color;cx.lineWidth=w;cx.beginPath();let started=false;for(const p of pts){const x=pad.l+pw*((p.d-1)/(maxD-1||1));const val=p[key];if(val<0)continue;const y=pad.t+ph-ph*(Math.min(val,maxY)/maxY);if(!started){cx.moveTo(x,y);started=true}else cx.lineTo(x,y)}cx.stroke()}plotLine(data,'logSing','#f59e0b',2.5);plotLine(data,'logHam','#60a5fa',2.5);let html='';const showDs=[1,2,3,5,Math.floor(L/4),Math.floor(L/2),L-1,L].filter((d,i,a)=>d>=1&&d<=L&&a.indexOf(d)===i);for(const d of showDs){const sing=Math.pow(A,L-d+1);const logS=(L-d+1)*Math.log10(A);const r=Math.floor((d-1)/2);const bs=ballSize(A,L,r);const ham=Math.floor(Math.pow(A,L)/bs);const logH=Math.log10(Math.max(ham,1));const tight=Math.min(logS,logH);const tightLabel=logS<=logH?'Singleton':'Hamming';html+=`<tr><td>${d}</td><td>${logS>12?'10^'+logS.toFixed(1):sing.toLocaleString()}</td><td>${logH>12?'10^'+logH.t