      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Hamming Space Explorer</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}h1{font-size:1.6em;margin-bottom:4px;color:#7eb8ff}h2{font-size:1em;color:#888;margin-bottom:20px;font-weight:normal}.container{display:flex;gap:30px;flex-wrap:wrap;justify-content:center;max-width:1100px;width:100%}.panel{background:#12122a;border:1px solid #2a2a4a;border-radius:12px;padding:20px;flex:1;min-width:320px}canvas{border-radius:8px;cursor:pointer;display:block;margin:0 auto 15px}label{font-size:.85em;color:#aaa}.controls{display:flex;gap:15px;flex-wrap:wrap;margin-bottom:15px;align-items:center}select,input[type=range]{background:#1a1a3a;color:#e0e0e0;border:1px solid #3a3a5a;border-radius:6px;padding:4px 8px;font-size:.85em}.info{background:#1a1a3a;border-radius:8px;padding:12px;font-size:.85em;line-height:1.6}.info b{color:#7eb8ff}.highlight{color:#ffcc00}table{width:100%;border-collapse:collapse;margin-top:10px;font-size:.8em}th,td{padding:6px 8px;text-align:center;border-bottom:1px solid #2a2a4a}th{color:#7eb8ff}</style></head><body><h1>🏛️ Hamming Space Explorer</h1><h2>The Library of Babel as a graph — volumes are nodes, Hamming neighbors are edges</h2><div class=\"container\"><div class=\"panel\"><canvas id=\"cubeCanvas\" width=\"460\" height=\"400\"></canvas><div class=\"controls\"><label>Selected: <select id=\"volSelect\"></select></label><label>Rotate: <input type=\"range\" id=\"rotSlider\" min=\"0\" max=\"360\" value=\"25\"></label></div><div class=\"info\" id=\"infoBox\">Click a node or select a volume to explore its neighbors.</div></div><div class=\"panel\"><h3 style=\"color:#7eb8ff;margin-bottom:10px\">📊 Library Statistics</h3><div class=\"controls\"><label>Alphabet A: <select id=\"alphaSelect\"><option value=\"2\" selected>2 (Binary)</option><option value=\"3\">3 (Ternary)</option><option value=\"4\">4 (DNA)</option></select></label><label>Length L: <select id=\"lenSelect\"><option value=\"2\">2</option><option value=\"3\" selected>3</option><option value=\"4\">4</option></select></label></div><div class=\"info\" id=\"statsBox\"></div><h3 style=\"color:#7eb8ff;margin:15px 0 10px\">📐 Singleton Bound</h3><table id=\"singletonTable\"><thead><tr><th>Min Dist d</th><th>Max |C|</th><th>Fraction</th></tr></thead><tbody></tbody></table></div></div><script>const c=document.getElementById('cubeCanvas'),ctx=c.getContext('2d'),sel=document.getElementById('volSelect'),rot=document.getElementById('rotSlider'),info=document.getElementById('infoBox'),stats=document.getElementById('statsBox'),alphaS=document.getElementById('alphaSelect'),lenS=document.getElementById('lenSelect'),stbl=document.getElementById('singletonTable').querySelector('tbody');let A=2,L=3,vols=[],edges=[],selected=0,angle=25;function init(){A=+alphaS.value;L=+lenS.value;vols=[];function gen(prefix){if(prefix.length===L){vols.push([...prefix]);return}for(let a=0;a<A;a++){prefix.push(a);gen(prefix);prefix.pop()}}gen([]);edges=[];for(let i=0;i<vols.length;i++)for(let j=i+1;j<vols.length;j++){let d=0;for(let k=0;k<L;k++)if(vols[i][k]!==vols[j][k])d++;if(d===1)edges.push([i,j])}sel.innerHTML='';vols.forEach((v,i)=>{const o=document.createElement('option');o.value=i;o.text=v.join('');sel.add(o)});selected=0;updateStats();draw()}function hd(i,j){let d=0;for(let k=0;k<L;k++)if(vols[i][k]!==vols[j][k])d++;return d}function updateStats(){const n=vols.length,deg=L*(A-1),diam=L;stats.innerHTML=`<b>Volumes:</b> A<sup>L</sup> = ${A}<sup>${L}</sup> = ${n}<br><b>Degree:</b> L×(A−1) = ${L}×${A-1} = <span class=\"highlight\">${deg}</span><br><b>Diameter:</b> <span class=\"highlight\">${diam}</span><br><b>Edges:</b> ${edges.length}`;stbl.innerHTML='';for(let d=1;d<=L;d++){const bound=Math.pow(A,L-d+1),frac=(bound/n).toExponential(2);stbl.innerHTML+=`<tr><td>${d}</td><td>${bound}</td><td>${frac}</td></tr>`}}function getPos(i){if(A===2&&L<=4){const bits=vols[i];let x=0,y=0,z=0;if(L>=1)x=bits[0]*2-1;if(L>=2)y=bits[1]*2-1;if(L>=3)z=bits[2]*2-1;if(L>=4){x+=(bits[3]*2-1)*.3;y+=(bits[3]*2-1)*.3}return[x,y,z]}const t=i/vols.length*Math.PI*2;const r=1+.3*Math.sin(i*3.7);return[r*Math.cos(t),r*Math.sin(t),.5*Math.sin(i*2.3)]}function project(x,y,z,a){const ca=Math.cos(a),sa=Math.sin(a);const rx=x*ca-z*sa,rz=x*sa+z*ca;const sc=200/(3+rz*.5);return[230+rx*sc,200+y*sc*-.9,rz]}function draw(){const a=angle*Math.PI/180;ctx.clearRect(0,0,c.width,c.height);const proj=vols.map((_,i)=>{const[x,y,z]=getPos(i);return project(x,y,z,a)});const nbrs=new Set();edges.forEach(([i,j])=>{if(i===selected||j===selected)nbrs.add(i===selected?j:i)});edges.forEach(([i,j])=>{const isNbr=i===selected||j===selected;ctx.beginPath();ctx.moveTo(proj[i][0],proj[i][1]);ctx.lineTo(proj[j][0],proj[j][1]);ctx.strokeStyle=isNbr?'rgba(126,184,255,0.7)':'rgba(100,100,140,0.2)';ctx.lineWidth=isNbr?2.5:1;ctx.stroke()});const order=[...Array(vols.length).keys()].sort((a,b)=>proj[a][2]-proj[b][2]);order.forEach(i=>{const[px,py]=proj[i];const isSelected=i===selected;const isNbr=nbrs.has(i);const r=isSelected?12:isNbr?9:6;ctx.beginPath();ctx.arc(px,py,r,0,Math.PI*2);if(isSelected){ctx.fillStyle='#ffcc00';ctx.shadowColor='#ffcc00';ctx.shadowBlur=15}else if(isNbr){ctx.fillStyle='#7eb8ff';ctx.shadowColor='#7eb8ff';ctx.shadowBlur=8}else{ctx.fillStyle='#4a4a6a';ctx.shadowBlur=0}ctx.fill();ctx.shadowBlur=0;if(vols.length<=32){ctx.fillStyle=isSelected?'#000':'#fff';ctx.font=(isSelected?'bold ':'')+`${isSelected?10:8}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(vols[i].join(''),px,py)}});const nbrList=[...nbrs].map(j=>vols[j].join('')).join(', ');info.innerHTML=`<b>Volume:</b> <span class=\"highlight\">${vols[selected].join('')}</span><br><b>Neighbors (dist=1):</b> ${nbrList}<br><b>Neighbor count:</b> ${nbrs.size} = L×(A−1) = ${L}×${A-1} ✓<br><b>Max distance from here:</b> ${Math.max(...vols.map((_,j)=>hd(selected,j)))}`}sel.onchange=()=>{selected=+sel.value;draw()};rot.oninput=()=>{angle=+rot.value;draw()};c.onclick=(e)=>{const rect=c.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;const a=angle*Math.PI/180;let best=-1,bestD=Infinity;vols.forEach((_,i)=>{const[x,y,z]=getPos(i);const[px,py]=project(x,y,z,a);const d=Math.hypot(px-mx,py-my);if(d<bestD){bestD=d;best=i}});if(bestD<20){selected=best;sel.value=best;draw()}};alphaS.onchange=init;lenS.onchange=init;init()</script></body></html>"
    },
    {
      "title": "Singleton Bound Calculator",
      "description": "Interactive calculator showing how the Singleton bound A^(L-d+1) constrains meaningful subsets of the Library for various parameters.",
      "html": "<!DOCTYPE html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1.0\"><title>Singleton Bound Calculator</title><style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',system-ui,sans-serif;background:#0a0a1a;color:#e0e0e0;display:flex;flex-direction:column;align-items:center;padding:20px;min-height:100vh}h1{font-size:1.5em;color:#7eb8ff;margin-bottom:4px}h2{font-size:.95em;color:#888;font-weight:normal;margin-bottom:20px}.main{max-width:800px;width:100%}.card{background:#12122a;border:1px solid #2a2a4a;border-radius:12px;padding:20px;margin-bottom:20px}.row{display:flex;gap:20px;flex-wrap:wrap;align-items:center;margin-bottom:15px}.slider-group{flex:1;min-width:200px}.slider-group label{display:block;font-size:.85em;color:#aaa;margin-bottom:4px}.slider-group input[type=range]{width:100%;accent-color:#7eb8ff}.slider-group .val{color:#ffcc00;font-weight:bold;font-size:1.1em}canvas{width:100%;border-radius:8px;margin-top:10px}.result{background:#1a1a3a;border-radius:8px;padding:15px;font-size:.9em;line-height:1.8}.result b{color:#7eb8ff}.formula{text-align:center;font-size:1.3em;color:#ffcc00;padding:15px 0;font-family:'Courier New',monospace}.bar-container{display:flex;align-items:center;gap:10px;margin:8px 0}.bar{height:22px;border-radius:4px;transition:width .3s}.bar-label{font-size:.8em;white-space:nowrap;min-width:60px}</style></head><body><h1>📏 Singleton Bound Calculator</h1><h2>|C| ≤ A<sup>(L − d + 1)</sup> — How much meaning can the Library hold?</h2><div class=\"main\"><div class=\"card\"><div class=\"row\"><div class=\"slider-group\"><label>Alphabet size A: <span class=\"val\" id=\"aVal\">4</span></label><input type=\"range\" id=\"aSlider\" min=\"2\" max=\"26\" value=\"4\"></div><div class=\"slider-group\"><label>Book length L: <span class=\"val\" id=\"lVal\">16</span></label><input type=\"range\" id=\"lSlider\" min=\"2\" max=\"32\" value=\"16\"></div></div><div class=\"formula\" id=\"formulaBox\">|C| ≤ 4^(16 − d + 1)</div></div><div class=\"card\"><canvas id=\"chart\" height=\"350\"></canvas></div><div class=\"card\"><h3 style=\"color:#7eb8ff;margin-bottom:10px\">Bound vs. Distance</h3><div id=\"barChart\"></div></div><div class=\"card result\" id=\"resultBox\"></div></div><script>const aS=document.getElementById('aSlider'),lS=document.getElementById('lSlider'),aV=document.getElementById('aVal'),lV=document.getElementById('lVal'),formula=document.getElementById('formulaBox'),chart=document.getElementById('chart'),barDiv=document.getElementById('barChart'),resBox=document.getElementById('resultBox'),ctx=chart.getContext('2d');function update(){const A=+aS.value,L=+lS.value;aV.textContent=A;lV.textContent=L;formula.innerHTML=`|C| ≤ ${A}<sup>(${L} − d + 1)</sup>`;const total=Math.pow(A,L);const data=[];for(let d=1;d<=L;d++){const bound=Math.pow(A,L-d+1);data.push({d,bound,logBound:Math.log10(Math.max(bound,1)),frac:bound/total})}const W=chart.width=chart.offsetWidth*2,H=chart.height=700;ctx.clearRect(0,0,W,H);const pad={l:70,r:30,t:30,b:50};const pw=W-pad.l-pad.r,ph=H-pad.t-pad.b;const maxLog=data[0].logBound;ctx.fillStyle='#1a1a3a';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#2a2a4a';ctx.lineWidth=1;for(let i=0;i<=5;i++){const y=pad.t+ph*(1-i/5);ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(W-pad.r,y);ctx.stroke();ctx.fillStyle='#888';ctx.font='20px sans-serif';ctx.textAlign='right';ctx.fillText((maxLog*i/5).toFixed(1),pad.l-8,y+6)}ctx.fillStyle='#888';ctx.font='20px sans-serif';ctx.textAlign='center';ctx.save();ctx.translate(16,H/2);ctx.rotate(-Math.PI/2);ctx.fillText('log₁₀(bound)',0,0);ctx.restore();ctx.fillText('Minimum distance d',W/2,H-8);ctx.beginPath();ctx.strokeStyle='#7eb8ff';ctx.lineWidth=3;data.forEach((p,i)=>{const x=pad.l+pw*(i/(data.length-1||1));const y=pad.t+ph*(1-p.logBound/maxLog);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke();data.forEach((p,i)=>{if(i%(Math.ceil(data.length/12))!==0&&i!==data.length-1)return;const x=pad.l+pw*(i/(data.length-1||1));const y=pad.t+ph*(1-p.logBound/maxLog);ctx.beginPath();ctx.arc(x,y,6,0,Math.PI*2);ctx.fillStyle='#ffcc00';ctx.fill();ctx.fillStyle='#aaa';ctx.font='18px sans-serif';ctx.textAlign='center';ctx.fillText(p.d,x,H-pad.b+25)});let html='';const maxBarLog=data[0].logBound;const step=Math.max(1,Math.floor(L/10));for(let i=0;i<data.length;i+=step){const p=data[i];const pct=Math.max(1,p.logBound/maxBarLog*100);html+=`<div class=\"bar-container\"><div class=\"bar-label\">d=${p.d}</div><div class=\"bar\" style=\"width:${pct}%;background:linear-gradient(90deg,#7eb8ff,#3a5a8a)\"></div><div class=\"bar-label\">${p.bound>1e12?'10^'+p.logBound.toFixed(1):p.bound.toLocaleString()}</div></div>`}barDiv.innerHTML=html;const degreeN=L*(A-1);resBox.innerHTML=`<b>Total Library size:</b> ${A}<sup>${L}</sup>${total<1e15?' = '+total.toLocaleString():' ≈ 10<sup>'+Math.log10(total).toFixed(1)+'</sup>'}<br><b>Degree (neighbors per volume):</b> ${degreeN.toLocaleString()}<br><b>Diameter:</b> ${L}<br><b>At d=${Math.min(Math.ceil(L/2),L)}:</b> bound = ${A}<sup>${L-Math.min(Math.ceil(L/2),L)+1}</sup>${Math.pow(A,L-Math.min(Math.ceil(L/2),L)+1)<1e15?' = '+Math.pow(A,L-Math.min(Math.ceil(L/2),L)+1).toLocaleString():''}<br><b>Interpretation:</b> As minimum distance increases, the maximum number of \"meaningful\" volumes drops exponentially — meaning is rare in the Library.`}aS.oninput=update;lS.oninput=update;update()</script></body></html>"
