2';ctx.lineWidth=1;ctx.stroke();if(selected!==null){const neg=(12-selected)%12;const[x1,y1]=posOf(selected),[x2,y2]=posOf(neg);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);const preserved=consonant.has(selected)&&consonant.has(neg);ctx.strokeStyle=preserved?'rgba(96,255,144,0.4)':'rgba(255,96,96,0.4)';ctx.lineWidth=3;ctx.setLineDash([8,6]);ctx.stroke();ctx.setLineDash([])}for(let i=0;i<12;i++){const[x,y]=posOf(i);const isSelected=i===selected;const isNeg=selected!==null&&i===(12-selected)%12;const isHov=i===hovered;const r=isSelected||isNeg?22:isHov?20:16;if(isSelected){ctx.beginPath();ctx.arc(x,y,r+8,0,Math.PI*2);ctx.fillStyle='rgba(240,192,64,0.15)';ctx.fill()}if(isNeg){ctx.beginPath();ctx.arc(x,y,r+8,0,Math.PI*2);const neg=(12-selected)%12;const preserved=consonant.has(selected)&&consonant.has(neg);ctx.fillStyle=preserved?'rgba(96,255,144,0.12)':'rgba(255,96,96,0.12)';ctx.fill()}ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=colorOf(i);ctx.globalAlpha=isSelected||isNeg||isHov?1:.6;ctx.fill();ctx.globalAlpha=1;ctx.strokeStyle=isSelected?'#fff':isNeg?'#ff8':'#333';ctx.lineWidth=isSelected||isNeg?2.5:1;ctx.stroke();ctx.fillStyle='#fff';ctx.font=(isSelected||isNeg)?'bold 12px sans-serif':'11px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(names[i],x,y)}requestAnimationFrame(draw)}canvas.addEventListener('mousemove',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;hovered=null;for(let i=0;i<12;i++){const[x,y]=posOf(i);if((mx-x)**2+(my-y)**2<400)hovered=i}});canvas.addEventListener('click',e=>{const rect=canvas.getBoundingClientRect();const mx=e.clientX-rect.left,my=e.clientY-rect.top;for(let i=0;i<12;i++){const[x,y]=posOf(i);if((mx-x)**2+(my-y)**2<400){selected=i;const neg=(12-i)%12;const srcCon=consonant.has(i),tgtCon=consonant.has(neg);const srcType=perfect.has(i)?'perfect':consonant.has(i)?'imperfect':'dissonant';const tgtType=perfect.has(neg)?'perfect':consonant.has(neg)?'imperfect':'dissonant';let html=`<b>${fullNames[i]}</b> (${i}) → <b>−${i} = ${neg}</b> → <b>${fullNames[neg]}</b><br>`;html+=`Source: <span style='color:${colorOf(i)}'>${srcType}</span> | `;html+=`Target: <span style='color:${colorOf(neg)}'>${tgtType}</span><br>`;if(srcCon&&tgtCon)html+=`<span class='ok'>✓ Consonance PRESERVED under voice swap.</span>`;else if(srcCon&&!tgtCon)html+=`<span class='err'>✗ Consonance BROKEN! The ${fullNames[i]} is consonant but the ${fullNames[neg]} is dissonant.</span><br>This is the voice-swap asymmetry: the bass voice is privileged.`;else if(!srcCon&&tgtCon)html+=`<span class='hl'>Dissonance becomes consonance under swap.</span>`;else html+=`Both dissonant — swap is neutral.`;info.innerHTML=html;break}}});draw()</script></body></html>"
