=[{A:2,L:4},{A:2,L:8},{A:4,L:16}];el.innerHTML=configs.map(c=>{const lv=logVolumes(c.A,c.L);const vols=Math.pow(c.A,c.L);let lse;if(vols<1000)lse=vols*lv;else lse=c.L*Math.pow(c.A,c.L)*Math.log10(c.A);return`<div class='comp-card'><div style='font-size:.75em;color:#888'>A=${c.A}, L=${c.L}</div><div class='comp-val' style='color:#4ecdc4'>${vols<=1e6?vols.toLocaleString():'10^'+lv.toFixed(0)}</div><div class='comp-label'>Volumes (A<sup>L</sup>)</div><div class='comp-val' style='color:#ff6b6b;margin-top:8px'>10<sup>${lse<1e6?lse.toFixed(0):lse.toExponential(1)}</sup></div><div class='comp-label'>Self-evaluations</div></div>`}).join('');ex.innerHTML=`<strong>No Universal Self-Evaluator Theorem:</strong> There is no pair (encode, decode) with decode ∘ encode = id, because the set of functions Volume→Volume is strictly larger than Volume itself. This is a finite analogue of Cantor's diagonal argument — the Library cannot contain its own complete catalog.`}function updateDegree(){const el=document.getElementById('degreeCards');const configs=[{A:2,L:8,name:'Binary Bytes'},{A:4,L:16,name:'DNA'},{A:25,L:1312000,name:'Borges'}];el.innerHTML=configs.map(c=>{const deg=c.L*(c.A-1);return`<div class='comp-card'><div style='font-size:.75em;color:#888'>${c.name} (A=${c.A}, L=${c.L.toLocaleString()})</div><div class='comp-val' style='color:#667eea'>${deg.toLocaleString()}</div><div class='comp-label'>Neighbors per volume</div><div style='font-size:.7em;color:#666;margin-top:4px'>${c.L.toLocaleString()} × ${c.A-1} = ${deg.toLocaleString()}</div></div>`}).join('')}document.getElementById('libSelect').onchange=updateProb;document.getElementById('targetLen').oninput=updateProb;renderScales();updateProb();updateCatalog();updateDegree()</script></body></html>"
