      "html": "<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{background:#1a1a2e;color:#e0e0e0;font-family:'Segoe UI',system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}h1{font-size:1.4em;margin-bottom:5px;color:#f0c040}h2{font-size:.9em;font-weight:normal;color:#888;margin-bottom:15px}.container{display:flex;gap:20px;flex-wrap:wrap;justify-content:center}canvas{border-radius:12px;background:#0d0d1a;cursor:pointer}.panel{background:#0d0d1a;border-radius:12px;padding:15px;min-width:260px;max-width:320px;font-size:.85em}.panel h3{color:#f0c040;margin-bottom:8px;font-size:1em}.stat{display:flex;justify-content:space-between;padding:3px 0;border-bottom:1px solid #222}.stat .label{color:#aaa}.stat .value{color:#fff;font-weight:bold}.legend{display:flex;gap:15px;margin-top:10px;font-size:.8em}.legend span{display:flex;align-items:center;gap:4px}.dot{width:10px;height:10px;border-radius:50%;display:inline-block}</style></head><body><h1>The Counterpoint Quiver</h1><h2>First-species voice leadings between consonant intervals (mod 12)</h2><div class='container'><canvas id='cv' width='520' height='520'></canvas><div class='panel'><h3 id='panelTitle'>Click an interval node</h3><div id='stats'></div><div class='legend'><span><span class='dot' style='background:#f0c040'></span> Perfect</span><span><span class='dot' style='background:#4090f0'></span> Imperfect</span></div></div></div><script>const C=[0,3,4,7,8,9],P=new Set([0,7]),N={0:'Unison',3:'m3',4:'M3',7:'P5',8:'m6',9:'M6'};function tgt(s,b,sp){return((s+sp-b)%12+12)%12}function isPar(b,s){return b===s&&b!==0}function perm(src,tg){let r=[];for(let b=0;b<12;b++)for(let s=0;s<12;s++){if(tgt(src,b,s)===tg&&C.includes(tg)&&!(P.has(tg)&&isPar(b,s)))r.push([b,s])}return r}const E={};C.forEach(i=>C.forEach(j=>{E[i+','+j]=perm(i,j).length}));const cv=document.getElementById('cv'),c