      "html": "<!DOCTYPE html><html lang='en'><head><meta charset='UTF-8'><title>Self-Loop Bottleneck</title><style>*{margin:0;padding:0;box-sizing:border-box}body{background:#1a1a2e;color:#e0e0e0;font-family:'Segoe UI',system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;padding:20px}h1{font-size:1.3em;color:#f0c040;margin-bottom:4px}h2{font-size:.85em;color:#888;font-weight:normal;margin-bottom:15px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;max-width:700px}.card{background:#0d0d1a;border-radius:10px;padding:12px;text-align:center;border:2px solid #222;transition:border-color .3s}.card.perfect{border-color:#f0c04055}.card.imperfect{border-color:#4090f055}.card h3{font-size:.95em;margin-bottom:2px}.card .sub{font-size:.75em;color:#888;margin-bottom:8px}.slots{display:flex;flex-wrap:wrap;justify-content:center;gap:4px;margin:8px 0}.slot{width:32px;height:32px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:.7em;font-weight:bold;transition:all .3s}.slot.allowed{background:#2a6ab0;color:#fff}.slot.forbidden{background:#8b1a1a;color:#ff6666;text-decoration:line-through}.slot.identity{background:#2e7d32;color:#aaffaa}.count{font-size:1.4em;font-weight:bold;margin-top:4px}.perfect .count{color:#f0c040}.imperfect .count{color:#4090f0}</style></head><body><h1>Self-Loop Bottleneck</h1><h2>Perfect consonances: 1 self-loop | Imperfect consonances: 12 self-loops</h2><div class='grid' id='grid'></div><script>const C=[0,3,4,7,8,9],P=new Set([0,7]),N={0:'Unison',3:'Minor 3rd',4:'Major 3rd',7:'Perfect 5th',8:'Minor 6th',9:'Major 6th'};const grid=document.getElementById('grid');C.forEach(iv=>{const isPf=P.has(iv);const card=document.createElement('div');card.className='card '+(isPf?'perfect':'imperfect');let slotsHtml='';let count=0;for(let d=0;d<12;d++){const isId=d===0;const isPar=d!==0;const forbidden=isPf&&isPar;if(!forbidden)count++;const cls=isId?'identity':(forbidden?'forbidden':'allowed');slotsHtm