      "html": "<!DOCTYPE html><html><head><meta charset='utf-8'><title>Counterpoint Quiver</title><style>*{margin:0;padding:0;box-sizing:border-box}body{background:#0a0a1a;color:#e0e0e0;font-family:'Segoe UI',system-ui,sans-serif;display:flex;flex-direction:column;align-items:center;min-height:100vh;padding:20px}h1{font-size:1.4em;margin-bottom:5px;color:#88ccff}h2{font-size:0.9em;font-weight:normal;color:#888;margin-bottom:15px}canvas{border-radius:12px;background:#12122a;cursor:pointer}#info{margin-top:12px;padding:10px 20px;background:#1a1a2e;border-radius:8px;font-size:0.85em;min-height:40px;text-align:center;max-width:600px}.legend{display:flex;gap:20px;margin-top:10px;font-size:0.8em}.legend span{display:flex;align-items:center;gap:5px}.dot{width:12px;height:12px;border-radius:50%;display:inline-block}</style></head><body><h1>The Counterpoint Quiver</h1><h2>First-Species Counterpoint over ZMod 12</h2><canvas id='c' width='600' height='600'></canvas><div id='info'>Click a node to explore its connections. Hover for details.</div><div class='legend'><span><span class='dot' style='background:#ff6b6b'></span> Perfect consonance</span><span><span class='dot' style='background:#4ecdc4'></span> Imperfect consonance</span></div><script>const canvas=document.getElementById('c'),ctx=canvas.getContext('2d'),info=document.getElementById('info');const intervals=[{id:0,name:'Unison (P1)',short:'P1',perfect:true},{id:3,name:'Minor 3rd',short:'m3',perfect:false},{id:4,name:'Major 3rd',short:'M3',perfect:false},{id:7,name:'Perfect 5th',short:'P5',perfect:true},{id:8,name:'Minor 6th',short:'m6',perfect:false},{id:9,name:'Major 6th',short:'M6',perfect:false}];const N=12,cx=300,cy=300,R=200;intervals.forEach((v,i)=>{const a=-Math.PI/2+2*Math.PI*i/6;v.x=cx+R*Math.cos(a);v.y=cy+R*Math.sin(a)});function edgeCount(s,t){if(s.perfect&&s.id===t.id)return 1;if(t.perfect&&s.id===t.id)return 1;return 12;}function computeEdges(){const edges=[];for(let i=0;i<intervals.length;i++)for(let j=0;j